using System;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Staff.Subway;
public static class ElevationSkySetup {
 [MenuItem("STAFF/Subway/Apply Elevation Sky Tuning")]
 public static void Install(){if(EditorApplication.isPlaying)throw new Exception("Exit Play mode first.");var sky=UnityEngine.Object.FindFirstObjectByType<SubwayTimeOfDay>();if(!sky||!sky.atmosphere)throw new Exception("Open subway scene.");Directory.CreateDirectory("Library/StaffSubway");EditorSceneManager.SaveScene(sky.gameObject.scene,"Library/StaffSubway/before-elevation-sky.unity",true);Undo.RecordObjects(new UnityEngine.Object[]{sky,sky.atmosphere},"Elevation sky tuning");var a=sky.atmosphere;a.sunIntensity=1;a.elevationSunSize=true;a.horizonRadiusMultiplier=1.18f;a.horizonRadiusFadeDegrees=20;a.elevationOzone=true;a.horizonOzone=.6f;a.noonOzone=2.5f;a.ozoneStartDegrees=20;a.ozoneFullDegrees=60;var s=sky.solarEffects;s.hexGhostCount=6;s.roundGhostCount=3;s.hexGhostOpacity=.53f;s.roundGhostOpacity=1;s.hexGhostSize=1.3f;s.roundGhostSize=1.8f;a.Tick(true);sky.ApplySky();EditorUtility.SetDirty(a);EditorUtility.SetDirty(sky);EditorSceneManager.MarkSceneDirty(sky.gameObject.scene);EditorSceneManager.SaveScene(sky.gameObject.scene);Debug.Log("Elevation sky tuning saved: intensity 1, horizon radius +18%, ozone .6 at <=20 degrees to 2.5 at 60 degrees, approved ghost values.");}
}
